// JS Date has no naive/aware distinction: every Date is always a UTC instant,
// so no equivalent comparison error can occur; the comparison always succeeds.
const a = new Date(Date.UTC(2024, 0, 1));
const b = new Date(Date.UTC(2024, 0, 1));
console.log('a < b:', a < b, '| a.getTime() === b.getTime():', a.getTime() === b.getTime());
